import {ferryCases,ferryCopy as copy,ferryNames} from './ferry-content.mjs';
import {FERRY_DRAW as D,createFerry,ferryCase,ferryModel,stepFerryClock,setFerryFrame,resetFerry,ferryExample,ferrySigned} from './ferry-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fill=(text,values)=>text.replace(/\{([^}]+)\}/g,(whole,key)=>Object.hasOwn(values,key)?String(values[key]):whole);
const p=text=>`<p data-ferry-read>${esc(text)}</p>`;
const button=(action,label,{disabled=false,attrs=''}={})=>`<button type="button" data-ferry-action="${action}"${disabled?' disabled':''} ${attrs}>${esc(label)}</button>`;
const observerName=frame=>({bank:'the bank marker',ferry:'the ferry origin',other:'the other-boat origin'}[frame]);
const direction=u=>u<0?'left':u>0?'right':'staying at the same position in this view';
const spoken=n=>n<0?`negative ${Math.abs(n)}`:n>0?`positive ${n}`:'zero';
let visit=null;
export function resetFerryVisit(){visit=null;}
function current(notebook,owner){
 if(!visit||visit.notebook!==notebook||visit.owner!==owner)visit={notebook,owner,caseId:'riding',cases:new Map(),example:false,part:0,pending:''};
 if(!visit.cases.has(visit.caseId))visit.cases.set(visit.caseId,{material:createFerry(visit.caseId),readings:false,explanation:false});
 return visit;
}
export const ferryEntry=()=>`<aside class="ferry-entry"><a href="#post/ferry">Ferry Deck</a><p>One crossing. Three ways to watch. What moves compared with you?</p></aside>`;
function scene(m){
 const o=m.byId,frame=m.material.frame,view=observerName(frame),title=`Same crossing at ${m.material.time} seconds, compared with ${view}. Right is positive. ${m.objects.map(x=>`${x.name}: position ${spoken(x.position)} meters, velocity ${spoken(x.velocity)} meters per second compared with ${view}`).join('. ')}. The courier stays on the ferry; the other boat is in a parallel lane.`;
 return `<div class="ferry-scene"><svg viewBox="0 0 600 230" preserveAspectRatio="none" role="img" aria-labelledby="ferry-scene-title" data-ferry-scene><title id="ferry-scene-title">${esc(title)}</title><rect width="600" height="58" class="ferry-shore"/><rect y="58" width="600" height="172" class="ferry-water"/><line class="ferry-origin-guide" x1="300" y1="8" x2="300" y2="214"/><g data-ferry-object="bank" transform="translate(${o.bank.x} 0)" class="ferry-bank-mark${frame==='bank'?' ferry-observer':''}"><line x1="0" y1="15" x2="0" y2="54"/><path d="M0 10L7 19L0 28L-7 19Z"/><circle data-ferry-origin cx="0" cy="36" r="4"/></g><g class="ferry-platform"><polygon data-ferry-hull points="${m.deck.from},108 ${m.deck.to},108 ${m.deck.to-8},136 ${m.deck.from+8},136"/><line data-ferry-deck x1="${m.deck.from}" y1="108" x2="${m.deck.to}" y2="108"/></g><g data-ferry-object="ferry" transform="translate(${o.ferry.x} 0)" class="ferry-ferry-mark${frame==='ferry'?' ferry-observer':''}"><line x1="0" y1="99" x2="0" y2="132"/><circle data-ferry-origin cx="0" cy="125" r="4"/></g><g data-ferry-object="courier" transform="translate(${o.courier.x} 0)" class="ferry-courier"><circle cx="0" cy="85" r="5"/><path d="M-6 92L6 92L4 101L-4 101Z"/><path d="M-3 100L-4 108M3 100L4 108" fill="none"/><rect x="2" y="92" width="5" height="5"/><circle data-ferry-origin cx="0" cy="108" r="3"/></g><g class="ferry-other-hull"><polygon data-ferry-other-hull points="${m.otherHull.from},166 ${m.otherHull.to},166 ${m.otherHull.to-4},180 ${m.otherHull.from+4},180"/></g><g data-ferry-object="other" transform="translate(${o.other.x} 0)" class="ferry-other-mark${frame==='other'?' ferry-observer':''}"><circle data-ferry-origin cx="0" cy="173" r="4"/></g><line class="ferry-axis" x1="60" y1="214" x2="540" y2="214"/>${m.positionTicks.map(t=>`<line class="ferry-tick" x1="${t.x}" y1="208" x2="${t.x}" y2="220"/>`).join('')}</svg><div class="ferry-scale" aria-hidden="true">${m.positionTicks.map(t=>`<span style="left:${t.x/6}%">${ferrySigned(t.value)}</span>`).join('')}</div></div>`;
}
function velocity(m){
 const a=m.velocityArrow,view=observerName(m.material.frame),u=m.byId.courier.velocity;
 return `<div class="ferry-velocity"><h3 data-ferry-read>Courier velocity · meters per second</h3><svg viewBox="0 0 600 60" role="img" aria-labelledby="ferry-velocity-title" data-ferry-velocity><title id="ferry-velocity-title">${esc(`Courier velocity compared with ${view}: ${spoken(u)} meters per second. ${direction(u)}. Separate velocity scale, not a position or traveled path.`)}</title><line class="ferry-axis" x1="140" y1="30" x2="460" y2="30"/>${m.velocityTicks.map(t=>`<line class="ferry-tick" x1="${t.x}" y1="24" x2="${t.x}" y2="36"/>`).join('')}<g transform="translate(0 30)">${a.kind==='zero'?'<circle data-ferry-zero cx="300" cy="0" r="5"/>':`<line data-ferry-velocity-shaft x1="${a.from[0]}" y1="0" x2="${a.shaftEnd[0]}" y2="0" stroke-width="4" stroke-linecap="butt"/><polygon data-ferry-velocity-head points="${a.head.map(p=>p.join(',')).join(' ')}"/>`}</g></svg><div class="ferry-scale" aria-hidden="true">${m.velocityTicks.map(t=>`<span style="left:${t.x/6}%">${ferrySigned(t.value)}</span>`).join('')}</div>${p(`${ferrySigned(u)} m/s compared with ${view}: ${direction(u)}.`)}</div>`;
}
function figure(m){const view=observerName(m.material.frame),q=m.byId.courier.position;return `<figure class="ferry-material" data-ferry-material><figcaption>${p(fill(copy.viewCaption,{observer:view,t:m.material.time}))}</figcaption>${scene(m)}<p class="ferry-axis-caption" data-ferry-read>${esc(fill(copy.axisCaption,{observer:view}))}</p><p class="ferry-key" data-ferry-read><span>◆ Bank marker</span><span>● Ferry origin</span><span>▣ Courier</span><span>◇ Other-boat origin</span></p><p class="ferry-position" data-ferry-read>Courier: <strong>${ferrySigned(q)} m</strong> from ${esc(view)}.</p>${velocity(m)}<p class="ferry-velocity-key" data-ferry-read>${esc(fill(copy.velocityLegend,{observer:view}))}</p></figure>`;}
function controls(m,e){return `<div class="ferry-tools"><div class="ferry-view-buttons" role="group" aria-label="Choose what to compare motion with">${[['bank','Watch from bank'],['ferry','Watch from ferry'],['other','Watch from other boat']].map(([id,label])=>button('view',label,{attrs:`data-ferry-frame="${id}" aria-pressed="${m.material.frame===id}"`})).join('')}</div><section class="ferry-clock" aria-label="Crossing clock"><h3>Clock <strong>${m.material.time} s</strong></h3><div class="ferry-clock-buttons">${button('back','Back one second',{disabled:!m.canBack})}${button('forward','Forward one second',{disabled:!m.canForward})}</div>${button('reset','Reset this crossing')}<p>${esc(copy.endpoint)}</p></section><div class="ferry-actions">${button('readings',e.readings?'Hide readings':'Show readings',{attrs:`aria-expanded="${e.readings}"`})}${button('explain',e.explanation?'Hide explanation':'Explain this view',{attrs:`aria-expanded="${e.explanation}"`})}${button('example','Show an example')}${hearButton('','Hear this crossing')}</div></div>`;}
function readings(m){return `<section class="ferry-readings"><table><caption data-ferry-read>The same moment at ${m.material.time} s, compared with ${esc(observerName(m.material.frame))}. Right is positive.</caption><thead><tr data-ferry-read><th scope="col">Thing</th> <th scope="col">Position (m)</th> <th scope="col">Velocity (m/s)</th></tr></thead><tbody>${m.objects.map(o=>`<tr data-ferry-read><th scope="row">${esc(o.name)}</th> <td>${ferrySigned(o.position)}</td> <td>${ferrySigned(o.velocity)} <span>${o.velocity===0?'no position change':o.direction}</span></td></tr>`).join('')}</tbody></table></section>`;}
function explanation(m){const view=observerName(m.material.frame),u=m.byId.courier.velocity,v=m.byId.courier.bankVelocity,observer=m.observer.velocity;return `<section class="ferry-explanation" aria-labelledby="ferry-explanation-title"><h3 id="ferry-explanation-title" tabindex="-1" data-ferry-read>Why can both descriptions work?</h3>${p(m.case.explanation)}${p(`Courier relative to ${view}: courier relative to bank (${ferrySigned(v)} m/s) minus ${view} relative to bank (${ferrySigned(observer)} m/s) = ${ferrySigned(u)} m/s.`)}${p(fill(copy.explanation,{observer:view}))}</section>`;}
function working(v,e){const m=ferryModel(e.material);return `<h2 id="ferry-title" tabindex="-1" data-ferry-read>${esc(m.case.request)}</h2>${p(copy.notice)}<div class="ferry-workbench">${figure(m)}${controls(m,e)}</div>${e.readings?readings(m):''}${e.explanation?explanation(m):''}`;}
function example(v){const f=ferryExample(v.part);return `<h2 id="ferry-title" tabindex="-1" data-ferry-read>${esc(f.title)}</h2><p class="ferry-example-label" data-ferry-read>Worked example, not your crossing. Part ${v.part+1} of 4.</p><div class="ferry-example-actions">${button('example-back','Previous example part',{disabled:v.part===0})}${button('example-next','Next example part',{disabled:v.part===3})}${button('example-close','Return to my crossing')}${hearButton('','Hear this example')}</div>${p(f.text)}${figure(f.model)}`;}
export function ferryPage(notebook,owner){const v=current(notebook,owner),e=v.cases.get(v.caseId);return `<section class="panel ferry-bench" data-ferry-root data-ferry-mode="${v.example?'example':'live'}"><header class="ferry-header"><div><h1>Ferry Deck</h1><p>One crossing · three ways to watch</p></div><nav aria-label="Ferry Deck exits"><a href="#post">Post Office</a><a href="#desk">Keeper’s Desk</a><a href="#notes">Grown-up notes</a></nav></header><label class="ferry-case-label">Choose a crossing <select data-ferry-case>${ferryCases.map(c=>`<option value="${c.id}"${c.id===v.caseId?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${v.example?example(v):working(v,e)}<p class="ferry-status" role="status" aria-live="polite" aria-atomic="true"></p><p class="ferry-visit">${esc(copy.visit)}</p><a href="#desk/gaps">Explore positions and gaps</a><details class="ferry-about"><summary>About this model</summary>${p(copy.opening)}${p(copy.units)}${p(copy.parent)}</details></section>`;}
export function bindFerry(notebook,ctx){
 const root=document.querySelector('[data-ferry-root]');if(!root||!visit)return;
 const v=visit,owner=v.owner,id=v.caseId,e=v.cases.get(id),material=e.material,exampleOpen=v.example,part=v.part,read=e.readings,explaining=e.explanation;
 const live=()=>root.isConnected&&document.querySelector('[data-ferry-root]')===root&&location.hash==='#post/ferry'&&visit===v&&v.caseId===id&&v.cases.get(id)===e&&e.material===material&&v.example===exampleOpen&&v.part===part&&e.readings===read&&e.explanation===explaining&&(!ctx.isActive||ctx.isActive())&&ctx.notebook()===notebook&&ctx.explorerId()===owner;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 if(v.pending)requestAnimationFrame(()=>requestAnimationFrame(()=>{if(live()){root.querySelector('.ferry-status').textContent=v.pending;v.pending='';}}));
 function redraw(selector='#ferry-title'){ctx.render();let target=document.querySelector(selector);if(!target||target.disabled)target=document.querySelector('#ferry-title');if(target){target.focus({preventScroll:true});const r=target.getBoundingClientRect();if(r.top<0||r.bottom>innerHeight)target.scrollIntoView({block:'nearest'});}}
 function edit(next,action,selector){if(!next)return;stop();e.material=next;e.explanation=false;if(action==='reset'){e.readings=false;v.pending='This crossing returned to zero seconds, watching from the bank.';}else if(action==='view')v.pending=`${copy.sameMoment} Watching from ${observerName(next.frame)} at ${next.time} seconds.`;else v.pending=`Clock ${next.time} seconds. Still watching from ${observerName(next.frame)}.`;
  if(action==='back'&&next.time===0)selector='[data-ferry-action="forward"]';if(action==='forward'&&next.time===6)selector='[data-ferry-action="back"]';redraw(selector);
 }
 root.querySelector('[data-ferry-case]').addEventListener('change',event=>{if(!live()||!ferryCase(event.target.value)||event.target.value===id)return;stop();v.caseId=event.target.value;v.example=false;v.part=0;v.pending='';if(!v.cases.has(v.caseId))v.cases.set(v.caseId,{material:createFerry(v.caseId),readings:false,explanation:false});redraw('[data-ferry-case]');});
 root.querySelectorAll('[data-ferry-action]').forEach(b=>b.addEventListener('click',()=>{
  if(!live()||b.disabled)return;const a=b.dataset.ferryAction,selector=`[data-ferry-action="${a}"]`;
  if(!exampleOpen&&['back','forward'].includes(a)){edit(stepFerryClock(material,a==='forward'?1:-1),a,selector);return;}
  if(!exampleOpen&&a==='view'){edit(setFerryFrame(material,b.dataset.ferryFrame),a,`[data-ferry-frame="${b.dataset.ferryFrame}"]`);return;}
  if(!exampleOpen&&a==='reset'){edit(resetFerry(material),a,selector);return;}
  if(!exampleOpen&&a==='readings'){stop();e.readings=!e.readings;v.pending=e.readings?'Readings shown for this clock moment and observer.':'Readings hidden.';redraw(selector);return;}
  if(!exampleOpen&&a==='explain'){stop();e.explanation=!e.explanation;v.pending=e.explanation?'A supplied explanation of this view is shown.':'Explanation hidden.';redraw(e.explanation?'#ferry-explanation-title':selector);return;}
  if(!exampleOpen&&a==='example'){stop();v.example=true;v.part=0;v.pending='Worked example, not your crossing. Part 1 of 4.';redraw();return;}
  if(exampleOpen&&a==='example-close'){stop();v.example=false;v.pending='Your crossing restored with the same clock, view and settings.';redraw('[data-ferry-action="example"]');return;}
  if(exampleOpen&&['example-back','example-next'].includes(a)){const next=part+(a==='example-next'?1:-1);if(!ferryExample(next))return;stop();v.part=next;v.pending=`Worked example, not your crossing. Part ${next+1} of 4.`;redraw();}
 }));
 root.addEventListener('click',event=>{const b=event.target.closest?.('[data-speak]');if(!b||!root.contains(b))return;if(!live()){event.preventDefault();event.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-ferry-read]')].filter(x=>x.getClientRects().length&&getComputedStyle(x).visibility!=='hidden'&&!x.closest('details:not([open])')).map(x=>(x.innerText||x.textContent).trim().replace(/\s+/g,' ')).join(' ');},{capture:true});
}
